using Nockx.Base.CryptographyTypes.Rsa;

namespace Nockx.BaseTest.RsaPublicKeyTests;

public class ConstructionTests {
	[Fact]
	public void ConstructSuccess() => new RsaPublicKey(Convert.FromBase64String(""));

	[Fact]
	public void ConstructInvalidDataFail() => Assert.Throws<InvalidOperationException>(() => new RsaPublicKey(Convert.FromBase64String("")));

	[Fact]
	public void ConstructIncorrectKeyTypeFail() => Assert.Equal("Public RSA was attempted to be created with ML-KEM-768 key data", Assert.Throws<InvalidOperationException>(() => new RsaPublicKey(Convert.FromBase64String(""))).Message);
}